package com.gk.jobhelper.service;
import com.gk.jobhelper.dto.InterviewScoreImportResult;import com.gk.jobhelper.entity.*;import com.gk.jobhelper.mapper.*;import org.apache.poi.ss.usermodel.*;import org.apache.poi.xssf.usermodel.XSSFWorkbook;import org.junit.jupiter.api.Test;import org.mockito.ArgumentCaptor;import java.io.*;import java.nio.file.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.ArgumentMatchers.anyList;import static org.mockito.Mockito.*;
class InterviewScoreImportServiceTest {
 @Test void shouldAggregateByYearAndPositionCodeAndReportInvalidRows()throws Exception{JobInterviewScoreMapper scores=mock(JobInterviewScoreMapper.class);JobPositionMapper positions=mock(JobPositionMapper.class);JobPosition linked=new JobPosition();linked.setPositionCode("A001");when(positions.selectByPositionCodes(anyList())).thenReturn(Collections.singletonList(linked));InterviewScoreImportService service=new InterviewScoreImportService(new ExcelRowReader(),scores,positions);Path file=Files.createTempFile("interview-test-",".xlsx");write(file);try{InterviewScoreImportResult r=service.importFile(2026,file.toFile(),"test.xlsx");assertEquals(4,r.getRawRowCount());assertEquals(2,r.getAggregatedPositionCount());assertEquals(1,r.getInvalidRowCount());assertEquals(1,r.getLinkedPositionCount());assertEquals(1,r.getUnlinkedPositionCount());ArgumentCaptor<JobInterviewScore> c=ArgumentCaptor.forClass(JobInterviewScore.class);verify(scores,times(2)).upsert(c.capture());JobInterviewScore a=c.getAllValues().stream().filter(x->"A001".equals(x.getPositionCode())).findFirst().get();assertEquals("131.5",a.getMinInterviewScore().toPlainString());assertEquals(2,a.getInterviewCandidateCount());}finally{Files.deleteIfExists(file);}}
 private void write(Path path)throws Exception{try(Workbook w=new XSSFWorkbook()){Sheet s=w.createSheet("名单");String[] h={"招录机关","职位名称","职位代码","笔试成绩"};Row hr=s.createRow(0);for(int i=0;i<h.length;i++)hr.createCell(i).setCellValue(h[i]);row(s,1,"单位A","岗位A","A001","132.6");row(s,2,"单位A","岗位A","A001","131.5");row(s,3,"单位B","岗位B","B002","140");row(s,4,"单位C","岗位C","","bad");try(OutputStream out=Files.newOutputStream(path)){w.write(out);}}}private void row(Sheet s,int n,String...v){Row r=s.createRow(n);for(int i=0;i<v.length;i++)r.createCell(i).setCellValue(v[i]);}
 @Test void shouldDetectTitleRowAndRealScoreHeaderAlias()throws Exception{JobInterviewScoreMapper scores=mock(JobInterviewScoreMapper.class);JobPositionMapper positions=mock(JobPositionMapper.class);when(positions.selectByPositionCodes(anyList())).thenReturn(Collections.emptyList());InterviewScoreImportService service=new InterviewScoreImportService(new ExcelRowReader(),scores,positions);Path file=Files.createTempFile("interview-real-header-",".xlsx");try(Workbook w=new XSSFWorkbook()){Sheet s=w.createSheet("第一批进面名单");s.createRow(0).createCell(0).setCellValue("江西省2026年度考试录用公务员第一批进入面试人员名单");String[] h={"职位代码","部门名称","职位名称","准考证号","姓名","进入面试\n最低分"};Row hr=s.createRow(3);for(int i=0;i<h.length;i++)hr.createCell(i).setCellValue(h[i]);row(s,4,"100100201022","单位A","岗位A","136010201304","肖钰","134.74");try(OutputStream out=Files.newOutputStream(file)){w.write(out);}}try{InterviewScoreImportResult r=service.importFile(2026,file.toFile(),"real.xlsx");assertEquals(1,r.getAggregatedPositionCount());ArgumentCaptor<JobInterviewScore> c=ArgumentCaptor.forClass(JobInterviewScore.class);verify(scores).upsert(c.capture());assertEquals("134.74",c.getValue().getMinInterviewScore().toPlainString());}finally{Files.deleteIfExists(file);}}
 @Test void shouldReadWorkbookWhoseExtensionDoesNotMatchItsContent()throws Exception{JobInterviewScoreMapper scores=mock(JobInterviewScoreMapper.class);JobPositionMapper positions=mock(JobPositionMapper.class);when(positions.selectByPositionCodes(anyList())).thenReturn(Collections.emptyList());InterviewScoreImportService service=new InterviewScoreImportService(new ExcelRowReader(),scores,positions);Path file=Files.createTempFile("interview-mismatched-",".xls");try(Workbook w=new XSSFWorkbook()){Sheet s=w.createSheet("名单");String[] h={"招录机关","报考职位","职位代码","笔试总成绩"};Row hr=s.createRow(0);for(int i=0;i<h.length;i++)hr.createCell(i).setCellValue(h[i]);row(s,1,"单位A","岗位A","700110101006","135.20");try(OutputStream out=Files.newOutputStream(file)){w.write(out);}}try{InterviewScoreImportResult r=service.importFile(2026,file.toFile(),"fake.xls");assertEquals(1,r.getAggregatedPositionCount());verify(scores).upsert(any(JobInterviewScore.class));}finally{Files.deleteIfExists(file);}}
}
